{"requestId":"07d8f69feead4f77999e4c7d90e2ac42","modelId":"default-model","modelName":"Auto","isHelperMessage":false,"traceId":"2bcadbc8758317da706f385ce9eb37d8","toolStatus":{"call_706153b763524d1ba6b0f05f":{"ready":true,"status":"executed","args":{"filePath":"/Users/ff/Desktop/ProjectsAI/ProjectsHackathons/pawtner-emergency/shared/rules.ts"},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"/Users/ff/Desktop/ProjectsAI/ProjectsHackathons/pawtner-emergency/shared/rules.ts","content":"     1:import {
     2:  DEMO_RULES,
     3:  EMERGENCY_SYMPTOM_KEYWORDS,
     4:  HIGH_READING_SYMPTOM_KEYWORDS,
     5:  POSSIBLE_SIDE_EFFECT_KEYWORDS,
     6:} from "./config.js";
     7:import type { AgentDecision, AgentInput, DecisionKind, DogMood } from "./contract.js";
     8:import { DECISION_TEMPLATES } from "./templates.js";
     9:
    10:function includesAny(text: string, keywords: readonly string[]): boolean {
    11:  const normalized = text.toLowerCase();
    12:  return keywords.some((word) => normalized.includes(word));
    13:}
    14:
    15:function isHighReading(systolic: number, diastolic: number): boolean {
    16:  return systolic >= DEMO_RULES.highSystolic || diastolic >= DEMO_RULES.highDiastolic;
    17:}
    18:
    19:export function selectDogMood(heart: number, latestDecision: Pick<AgentDecision, "decision"> | null): DogMood {
    20:  if (latestDecision?.decision === "emergency_995" || latestDecision?.decision === "see_gp_soon") return "attentive";
    21:  if (latestDecision?.decision === "nudge") return "sleepy";
    22:  if (latestDecision?.decision === "celebrate" || heart >= DEMO_RULES.heartMaximum) return "joyful";
    23:  if (latestDecision?.decision === "restock_reminder" || latestDecision?.decision === "doctor_question") return "content";
    24:  if (heart <= 1) return "sleepy";
    25:  return "content";
    26:}
    27:
    28:function decision(
    29:  input: AgentInput,
    30:  kind: DecisionKind,
    31:  ruleId: string,
    32:  reasoning: string,
    33:  observations: AgentDecision["observations"],
    34:  caretakerPing = false,
    35:): AgentDecision {
    36:  const base = {
    37:    id: `decision-${Date.parse(input.now)}`,
    38:    decision: kind,
    39:    ruleId,
    40:    observations,
    41:    reasoning,
    42:    wording: DECISION_TEMPLATES[kind],
    43:    wordingSource: "template" as const,
    44:    caretakerPing,
    45:    refused: false,
    46:    createdAt: input.now,
    47:  };
    48:  return { ...base, mood: selectDogMood(input.dog.heart, { decision: kind }) };
    49:}
    50:
    51:export function decide(input: AgentInput): AgentDecision {
    52:  const nowMs = Date.parse(input.now);
    53:  const metrics = input.healthMetrics.filter((metric) => Date.parse(metric.recordedAt) <= nowMs);
    54:  const latestMetric = [...metrics].sort((a, b) => Date.parse(b.recordedAt) - Date.parse(a.recordedAt))[0];
    55:  const latestNote = latestMetric?.note ?? "";
    56:  const emergencyNote = metrics.find((metric) => includesAny(metric.note ?? "", EMERGENCY_SYMPTOM_KEYWORDS));
    57:  const highReadingSymptom = latestMetric && isHighReading(latestMetric.systolic, latestMetric.diastolic)
    58:    && includesAny(latestNote, HIGH_READING_SYMPTOM_KEYWORDS);
    59:
    60:  if (emergencyNote || highReadingSymptom) {
    61:    return decision(input, "emergency_995", emergencyNote ? "emergency_symptom_note" : "bp_high_with_symptom",
    62:      "A configured emergency symptom or a symptom with a high reading was recorded; emergency wording is fixed and uses no model.",
    63:      { symptomDetected: true, highReading: Boolean(highReadingSymptom) });
    64:  }
    65:
    66:  const repeatedHighReadings = metrics.filter((metric) => {
    67:    const withinWindow = nowMs - Date.parse(metric.recordedAt) <= DEMO_RULES.repeatedHighReadingWindowDays * 86_400_000;
    68:    return withinWindow && metric.systolic >= DEMO_RULES.repeatedHighReadingSystolic && metric.diastolic >= DEMO_RULES.repeatedHighReadingDiastolic;
    69:  });
    70:  if (latestMetric && isHighReading(latestMetric.systolic, latestMetric.diastolic)) {
    71:    return decision(input, "see_gp_soon", "bp_high_without_symptom",
    72:      "A blood-pressure reading met a configured demo threshold without a detected symptom.",
    73:      { systolic: latestMetric.systolic, diastolic: latestMetric.diastolic, symptomDetected: false });
    74:  }
    75:  if (repeatedHighReadings.length >= DEMO_RULES.repeatedHighReadingsRequired) {
    76:    return decision(input, "see_gp_soon", "repeated_high_readings_7d",
    77:      "Three or more readings met the configured demo threshold in the seven-day window.",
    78:      { qualifyingReadings: repeatedHighReadings.length, windowDays: DEMO_RULES.repeatedHighReadingWindowDays });
    79:  }
    80:
    81:  const sideEffectMetric = [...metrics].reverse().find((metric) => includesAny(metric.note ?? "", POSSIBLE_SIDE_EFFECT_KEYWORDS));
    82:  if (sideEffectMetric) {
    83:    return decision(input, "doctor_question", "possible_side_effect_note",
    84:      "A note contains a configured possible-side-effect keyword; add it as a question for a professional.",
    85:      { noteRecordedAt: sideEffectMetric.recordedAt });
    86:  }
    87:
    88:  const caretaker = input.caretaker;
    89:  if (caretaker?.optedIn && caretaker.threshold >= DEMO_RULES.caretakerMinimumThreshold
    90:      && input.consecutiveMissedDoses >= caretaker.threshold) {
    91:    return decision(input, "nudge", "repeated_misses_caretaker_check_in",
    92:      "Consecutive missed doses reached the opted-in caretaker threshold.",
    93:      { consecutiveMissedDoses: input.consecutiveMissedDoses, caretakerThreshold: caretaker.threshold }, true);
    94:  }
    95:
    96:  const missedDose = input.doses.find((dose) => {
    97:    if (dose.status !== "missed" || dose.nudgeCount >= DEMO_RULES.maxNudgesPerDose) return false;
    98:    if (dose.nudgeCount === 0) {
    99:      return nowMs - Date.parse(dose.scheduledAt) >= DEMO_RULES.nudgeDelayMinutes * 60_000;
   100:    }
   101:    return dose.nudgeCount === 1 && dose.lastNudgeAt !== null
   102:      && nowMs - Date.parse(dose.lastNudgeAt) >= DEMO_RULES.nudgeIntervalMinutes * 60_000;
   103:  });
   104:  if (missedDose) {
   105:    const second = missedDose.nudgeCount === 1;
   106:    return decision(input, "nudge", second ? "dose_nudge_2" : "dose_nudge_1",
   107:      second ? "The dose remains untaken at least 60 minutes after the first nudge." : "The dose remains untaken at least 60 minutes after its scheduled time.",
   108:      { scheduleId: missedDose.id, nudgeCount: missedDose.nudgeCount + 1 });
   109:  }
   110:
   111:  const supplyEntry = Object.entries(input.daysOfSupplyByMedicationId)
   112:    .find(([, days]) => days !== null && days <= DEMO_RULES.restockDaysOfSupply);
   113:  if (supplyEntry) {
   114:    return decision(input, "restock_reminder", "low_days_of_supply",
   115:      "A medication's remaining supply reached the configured reminder threshold.",
   116:      { medicationId: supplyEntry[0], daysOfSupply: supplyEntry[1] });
   117:  }
   118:  if (input.latestDoseEvent?.event === "taken" || input.walkFinished || input.streakMilestoneReached) {
   119:    return decision(input, "celebrate", "care_milestone_completed",
   120:      "A dose, walk or streak milestone was completed.",
   121:      { doseTaken: input.latestDoseEvent?.event === "taken", walkFinished: Boolean(input.walkFinished), streakMilestoneReached: Boolean(input.streakMilestoneReached) });
   122:  }
   123:  return decision(input, "stay_quiet", "nothing_needs_attention", "No configured rule currently needs attention.", { heart: input.dog.heart });
   124:}
   125:","totalLineCount":125,"hasMore":false,"hint":""}}}}}

