{"role":"assistant","content":[{"type":"text","text":"Now update DogStage.css to replace the wiggle with hop, hearts, and bubble animations:"},{"type":"tool-call","toolCallId":"call_239b661a2eb8479caafb269f","toolName":"write_to_file","args":{"filePath":"/Users/ff/Desktop/ProjectsAI/ProjectsHackathons/pawtner-emergency/mobile/src/components/DogStage.css","content":"/* The stage is a size container: the dog is sized from the slot it was given, never from the viewport. */
.dog-stage {
  position: relative;
  width: 100%;
  height: 100%;
  container-type: size;
}

.dog-stage__figure {
  position: absolute;
  left: 50%;
  bottom: 0;
  height: min(100cqh, max(var(--dog-min, 0px), min(var(--dog-max, 100cqh), calc((100cqh - var(--top-overlap, 0px)) * 0.92))));
  transform: translateX(-50%);
}

.dog-stage__pet {
  position: relative;
  display: block;
  height: 100%;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  transform-origin: 50% 100%;
}

.dog-stage__body {
  position: relative;
  display: block;
  height: 100%;
  transform-origin: 50% 100%;
}

.dog-stage__image {
  display: block;
  height: 100%;
  width: auto;
  max-width: 72cqw;
  object-fit: contain;
  object-position: center bottom;
  user-select: none;
}

.dog-stage__glow {
  position: absolute;
  left: 50%;
  bottom: 8%;
  width: 150%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(255, 236, 190, 0.75), rgba(255, 236, 190, 0));
  opacity: var(--dog-glow, 0.5);
  transform: translateX(-50%);
  pointer-events: none;
}

.dog-stage__cast-shadow {
  position: absolute;
  left: 50%;
  bottom: -3%;
  width: 95%;
  height: 11%;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(25, 40, 22, 0.32), rgba(25, 40, 22, 0));
  transform: translateX(-62%);
  pointer-events: none;
}

.dog-stage__contact-shadow {
  position: absolute;
  left: 50%;
  bottom: -2%;
  width: 72%;
  height: 7%;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(20, 35, 20, 0.45), rgba(20, 35, 20, 0));
  transform: translateX(-50%);
  pointer-events: none;
}

/* ── Mood motion: transform and opacity only ── */
.dog-stage--content .dog-stage__body { animation: dog-breathe 3.6s ease-in-out infinite; }
.dog-stage--joyful .dog-stage__body { animation: dog-hop-mood 1.6s ease-in-out infinite; }
.dog-stage--sleepy .dog-stage__body { animation: dog-droop 5s ease-in-out infinite; }
/* attentive: still and upright, no playful motion */

/* ── Tap reactions (transform + opacity only) ── */

/* hop: a short jump with squash */
.dog-stage__pet.is-hop .dog-stage__body { animation: pet-hop 0.6s ease-out; }

/* hearts: 3 small hearts rise and fade (decoration only) */
.dog-stage__hearts {
  position: absolute;
  left: 50%;
  top: 0;
  width: 0;
  height: 0;
  pointer-events: none;
  z-index: 5;
}

.dog-stage__heart {
  position: absolute;
  color: #e85a6a;
  opacity: 0;
  transform: translateX(-50%) translateY(0) scale(0.5);
}

.dog-stage__heart--1 { left: -18px; animation: heart-rise 1.2s ease-out forwards; }
.dog-stage__heart--2 { left: 0; animation: heart-rise 1.2s ease-out 0.15s forwards; }
.dog-stage__heart--3 { left: 18px; animation: heart-rise 1.2s ease-out 0.3s forwards; }

/* bubble: speech bubble above the dog */
.dog-stage__bubble {
  position: absolute;
  left: 50%;
  bottom: 78%;
  transform: translateX(-50%);
  max-width: 200px;
  padding: 10px 16px;
  border-radius: 16px 16px 16px 4px;
  background: white;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
  line-height: 1.3;
  color: #2a4a36;
  text-align: center;
  white-space: normal;
  z-index: 6;
  pointer-events: none;
  /* Must not cover the top bar buttons — max-height keeps it below the top zone */
  max-height: 80px;
  overflow: hidden;
}

@keyframes dog-breathe {
  0%, 100% { transform: scale(1, 1); }
  50% { transform: scale(1.012, 1.03); }
}

@keyframes dog-hop-mood {
  0%, 55%, 100% { transform: translateY(0) scale(1, 1); }
  62% { transform: translateY(0) scale(1.04, 0.95); }
  75% { transform: translateY(-9%) scale(0.98, 1.03); }
  88% { transform: translateY(0) scale(1.03, 0.97); }
}

@keyframes dog-droop {
  0%, 100% { transform: rotate(0deg) translateY(0); }
  50% { transform: rotate(-2.5deg) translateY(1.5%); }
}

@keyframes pet-hop {
  0% { transform: translateY(0) scale(1, 1); }
  20% { transform: translateY(0) scale(1.08, 0.88); }
  50% { transform: translateY(-14%) scale(0.96, 1.04); }
  80% { transform: translateY(0) scale(1.05, 0.92); }
  100% { transform: translateY(0) scale(1, 1); }
}

@keyframes heart-rise {
  0% { opacity: 0; transform: translateX(-50%) translateY(20px) scale(0.5); }
  20% { opacity: 1; }
  100% { opacity: 0; transform: translateX(-50%) translateY(-50px) scale(1); }
}

/* Same specificity as the mood rules above, and later in the file, so this wins. */
@media (prefers-reduced-motion: reduce) {
  .dog-stage .dog-stage__body,
  .dog-stage__pet.is-hop .dog-stage__body,
  .dog-stage__heart--1,
  .dog-stage__heart--2,
  .dog-stage__heart--3 {
    animation: none;
  }
  .dog-stage__heart { opacity: 0; }
}
