{"role":"assistant","content":[{"type":"text","text":"Server is running. Now let me write a screenshot script:"},{"type":"tool-call","toolCallId":"call_9f4bcaf2c4954370b2b842c9","toolName":"write_to_file","args":{"filePath":"/Users/ff/Desktop/ProjectsAI/ProjectsHackathons/pawtner-emergency/screenshot-pet.mjs","content":"import { chromium } from "playwright";
import { mkdirSync } from "fs";
import { join } from "path";

const BASE = "http://localhost:5180";
const OUT = join(import.meta.dirname, "proof");

mkdirSync(OUT, { recursive: true });

const sizes = [
  { w: 360, h: 740, label: "360x740" },
  { w: 390, h: 844, label: "390x844" },
  { w: 430, h: 932, label: "430x932" },
  { w: 1280, h: 800, label: "1280x800" },
  { w: 360, h: 640, label: "360x640" },
];

async function shot(page, name) {
  const path = join(OUT, `${name}.png`);
  await page.screenshot({ path, fullPage: false });
  console.log(`  saved ${name}.png`);
}

async function navigateToHealth(page) {
  // Start at cover, click to begin
  await page.goto(BASE);
  await page.waitForTimeout(500);
  // Click cover to go to dedication
  await page.mouse.click(100, 400);
  await page.waitForTimeout(500);
  // Click dedication to go to home
  await page.mouse.click(100, 400);
  await page.waitForTimeout(500);
  // Click health nav
  const healthBtn = page.locator('.bottom-nav button:has-text("Health")');
  await healthBtn.click();
  await page.waitForTimeout(500);
}

async function fillBpForm(page, sys, dia, note) {
  const inputs = page.locator('.bp-form__input');
  await inputs.nth(0).fill(String(sys));
  await inputs.nth(1).fill(String(dia));
  if (note) {
    await inputs.nth(2).fill(note);
  }
  await page.locator('.bp-form__submit').click();
  await page.waitForTimeout(800);
}

async function openDecisionLog(page) {
  const btn = page.locator('.decision-log__toggle');
  if (await btn.count() > 0) {
    await btn.click();
    await page.waitForTimeout(300);
  }
}

async function tapDog(page) {
  // Click on the dog image
  const dog = page.locator('.dog-stage__pet');
  if (await dog.count() > 0) {
    await dog.click();
    await page.waitForTimeout(200);
  }
}

const browser = await chromium.launch({ headless: true });

for (const size of sizes) {
  console.log(`\n=== ${size.label} ===`);
  const context = await browser.newContext({
    viewport: { width: size.w, height: size.h },
    deviceScaleFactor: 2,
  });
  const page = await context.newPage();

  // 1. Health form (empty)
  await navigateToHealth(page);
  await shot(page, `health-form-${size.label}`);

  // 2. 185/120 + "bad headache" result with attentive dog
  await fillBpForm(page, 185, 120, "bad headache");
  await page.waitForTimeout(500);
  await shot(page, `emergency-result-${size.label}`);

  // 3. Decision log open
  await openDecisionLog(page);
  await shot(page, `decision-log-${size.label}`);

  // Close decision log
  await openDecisionLog(page);

  // 4. Pet reactions — go home first, then tap dog
  const homeBtn = page.locator('.back-button:has-text("Home")');
  if (await homeBtn.count() > 0) {
    await homeBtn.click();
    await page.waitForTimeout(500);
  }

  // hop (first tap)
  await tapDog(page);
  await page.waitForTimeout(150);
  await shot(page, `pet-hop-${size.label}`);

  // Wait for cooldown
  await page.waitForTimeout(700);

  // hearts (second tap)
  await tapDog(page);
  await page.waitForTimeout(300);
  await shot(page, `pet-hearts-${size.label}`);

  // Wait for cooldown
  await page.waitForTimeout(1300);

  // bubble (third tap)
  await tapDog(page);
  await page.waitForTimeout(300);
  await shot(page, `pet-bubble-${size.label}`);

  await context.close();
}

await browser.close();
console.log("\nDone.");
