     3:import type { DogMood } from "../../../shared/contract";
     4:
     5:export interface PetReactionState {
     6:  /** The current reaction being played, or null when idle. */
     7:  active: PetReactionKind | null;
     8:  /** Tap handler. Does nothing playful when mood is attentive or a reaction is playing. */
