    24:  const [active, setActive] = useState<PetReactionKind | null>(null);
    25:  const [bubbleLineIndex, setBubbleLineIndex] = useState(0);
    26:  const indexRef = useRef(0);
    27:  const audioRef = useRef<HTMLAudioElement | null>(null);
    28:  const audioFailedRef = useRef(false);
    29:  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    30:
    31:  // Check reduced-motion preference.
