    48:      const audio = new Audio(PET_REACTIONS.barkSoundPath);
    49:      audio.preload = "auto";
    50:      audio.addEventListener("error", () => {
    51:        audioFailedRef.current = true;
    52:      });
    53:      audioRef.current = audio;
    54:    } catch {
    55:      audioFailedRef.current = true;
    56:    }
    57:    return () => {
    58:      if (timerRef.current) clearTimeout(timerRef.current);
