          tabIndex={-1}
        >
          {isEmergency && (
            <>
              <p className="bp-result__number">{t("health.resultEmergencyNumber")}</p>
              <p className="bp-result__wording">{latestDecision.wording}</p>
            </>
          )}
          {isSeeGp && (
            <>
              <p className="bp-result__title">{t("health.resultSeeGpTitle")}</p>
              <p className="bp-result__wording">{latestDecision.wording}</p>
            </>
          )}
        </div>
      )}

