{"role":"assistant","content":[{"type":"text","text":"Good. Now let me write a verification script for the three scenarios:"},{"type":"tool-call","toolCallId":"write_to_file_120_90fec59f","toolName":"write_to_file","args":{"filePath":"/Users/ff/Desktop/ProjectsAI/ProjectsHackathons/pawtner-emergency/mobile/verify-emergency.mjs","content":"import { chromium } from "playwright";
import { join } from "path";

const BASE = "http://localhost:5180";
const OUT = join(import.meta.dirname, "..", "docs", "screenshots", "emergency-beat");

function centerX(width) {
  return width <= 430 ? width / 2 : 640;
}

async function skipIntro(page, width) {
  const cx = centerX(width);
  await page.mouse.click(cx, 400);
  await page.waitForTimeout(800);
  await page.mouse.click(cx, 400);
  await page.waitForTimeout(800);
}

async function navigateToHealth(page, width) {
  await page.goto(BASE);
  await page.waitForTimeout(800);
  await skipIntro(page, width);
  await page.waitForSelector('.bottom-nav button', { timeout: 5000 });
  await page.locator('.bottom-nav button').nth(2).click();
  await page.waitForTimeout(800);
}

async function navigateToHome(page, width) {
  await page.goto(BASE);
  await page.waitForTimeout(800);
  await skipIntro(page, width);
}

async function fillBpForm(page, sys, dia, note) {
  const inputs = page.locator('.bp-form__input');
  await inputs.nth(0).fill(String(sys));
  await inputs.nth(1).fill(String(dia));
  if (note) await inputs.nth(2).fill(note);
  await page.locator('.bp-form__submit').click();
  await page.waitForTimeout(800);
}

async function hasClass(page, selector, cls) {
  const el = page.locator(selector).first();
  return await el.evaluate((node, c) => node.classList.contains(c), cls);
}

async function getReactionClass(page) {
  const pet = page.locator('.dog-stage__pet');
  const classes = await pet.first().evaluate((node) => node.className);
  for (const kind of ["hop", "hearts", "bubble", "bark"]) {
    if (classes.includes(`is-${kind}`)) return kind;
  }
  return null;
}

async function getBubbleLine(page) {
  const bubble = page.locator('.dog-stage__bubble');
  if (await bubble.count() === 0) return null;
  return await bubble.first().textContent();
}

const browser = await chromium.launch({ headless: true });
let failed = false;

// ── Scenario 1: 185/120 + "bad headache" ──
console.log("\nScenario 1: 185/120 + bad headache");
{
  const ctx = await browser.newContext({ viewport: { width: 360, height: 640 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await navigateToHealth(page, 360);
  await fillBpForm(page, 185, 120, "bad headache");

  const resultVisible = await page.locator('.bp-result').isVisible();
  const number = await page.locator('.bp-result__number').textContent().catch(() => "");
  const toastVisible = await page.locator('.toast').isVisible().catch(() => false);
  const mood = await hasClass(page, '.dog-stage', 'dog-stage--attentive');

  console.log(`  result visible: ${resultVisible}`);
  console.log(`  number: ${number.trim()}`);
  console.log(`  toast visible: ${toastVisible}`);
  console.log(`  dog attentive: ${mood}`);

  // Tap the dog 3 times and check no reaction class appears
  for (let i = 0; i < 3; i++) {
    await page.locator('.dog-stage__pet').click();
    await page.waitForTimeout(200);
  }
  const reactionAfterTaps = await getReactionClass(page);
  console.log(`  reaction while attentive: ${reactionAfterTaps}`);

  if (!resultVisible || number.trim() !== "995" || toastVisible || !mood || reactionAfterTaps !== null) {
    console.log("  FAIL");
    failed = true;
  } else {
    console.log("  PASS");
  }

  await page.screenshot({ path: join(OUT, "verify-1-emergency-360x640.png") });
  await ctx.close();
}

// ── Scenario 2: 120/80 + no note ──
console.log("\nScenario 2: 120/80 + no note");
{
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await navigateToHealth(page, 390);
  await fillBpForm(page, 120, 80, "");

  const resultVisible = await page.locator('.bp-result').count() > 0;
  const toastText = await page.locator('.toast').textContent().catch(() => "");

  console.log(`  result visible: ${resultVisible}`);
  console.log(`  toast text: ${toastText.trim()}`);

  if (resultVisible || !toastText.trim().includes("heart is full")) {
    console.log("  FAIL");
    failed = true;
  } else {
    console.log("  PASS");
  }

  await page.screenshot({ path: join(OUT, "verify-2-normal-390x844.png") });
  await ctx.close();
}

// ── Scenario 3: 6 taps with no bark.mp3 ──
console.log("\nScenario 3: 6 taps with no bark.mp3");
{
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await navigateToHome(page, 390);
  // Give the browser a moment to fail loading the missing bark.mp3.
  await page.waitForTimeout(800);

  const sequence = [];
  for (let i = 0; i < 6; i++) {
    await page.locator('.dog-stage__pet').click();
    await page.waitForTimeout(150);
    const reaction = await getReactionClass(page);
    if (reaction === "bubble") {
      const line = await getBubbleLine(page);
      sequence.push(`${reaction}:${line?.trim()}`);
    } else {
      sequence.push(reaction);
    }
    // Wait for the reaction to clear (max bubble duration is 2400ms).
    await page.waitForTimeout(i % 3 === 2 ? 2600 : 900);
  }

  console.log(`  sequence: ${sequence.join(", ")}`);
  const expected = [
    "hop",
    "hearts",
    "bubble:Woof! max is happy you're here!",
    "hop",
    "hearts",
    "bubble:Tap again! max loves the attention.",
  ];
  if (JSON.stringify(sequence) !== JSON.stringify(expected)) {
    console.log("  FAIL");
    failed = true;
  } else {
    console.log("  PASS");
  }

  await ctx.close();
}

await browser.close();
process.exit(failed ? 1 : 0);
